fixed:
struct node *partition_around(struct node *h, int x){
  struct node *less = NULL, *more = NULL, *lt = NULL, *mt = NULL;
  while(h){
    struct node *next = h->next;
    h->next = NULL;
    if(h->val < x){
      if(!lt) less = h; else lt->next = h;
      lt = h;
    } else {
      if(!mt) more = h; else mt->next = h;
      mt = h;
    }
    h = next;
  }
  if(lt) lt->next = more;
  return less ? less : more;
}

