fixed:
int append_str(const char *p, const char *s){
  int fd = open(p, O_WRONLY | O_APPEND);
  if(fd < 0) return -1;
  const char *b = s;
  size_t left = strlen(s);
  while(left){
    ssize_t w = write(fd, b, left);
    if(w <= 0) break;
    b += w; left -= w;
  }
  close(fd);
  return left == 0 ? 0 : -1;
}

